import { Request, Response } from 'express';
import { query, withTransaction, Queryable } from '../config/db';
import { AppError } from '../middleware/errorHandler';
import { postVoucher, removeVoucher } from '../services/posting';
import { resolveFinancialYear, toDateString } from '../services/financialYear';
import { docTypeForVoucherType, peekNextNumber } from '../services/numberSeries';

/** Vouchers generated by invoices/payments must be changed through those documents. */
const assertNotLinked = async (db: Queryable, voucherId: string) => {
    const inv = await db.query('SELECT invoice_number FROM invoices WHERE voucher_id = $1', [voucherId]);
    if (inv.rows.length) {
        throw new AppError(`This voucher belongs to invoice ${inv.rows[0].invoice_number}. Edit the invoice instead.`, 400);
    }
    const pay = await db.query('SELECT 1 FROM payments WHERE voucher_id = $1', [voucherId]);
    if (pay.rows.length) throw new AppError('This voucher belongs to an invoice payment. Change it from the invoice.', 400);
    const rec = await db.query('SELECT 1 FROM receipts WHERE voucher_id = $1', [voucherId]);
    if (rec.rows.length) throw new AppError('This voucher belongs to a receipt/payment. Change it from Receipts & Payments.', 400);
};

export const createVoucher = async (req: Request, res: Response) => {
    const { voucherTypeId, voucherNumber, date, narration, entries } = req.body;
    const voucher = await withTransaction((db) =>
        postVoucher(db, { companyId: req.company!.id, voucherTypeId, voucherNumber, date, narration, entries })
    );
    res.status(201).json({ status: 'success', data: { voucher } });
};

export const updateVoucher = async (req: Request, res: Response) => {
    const { voucherTypeId, voucherNumber, date, narration, entries } = req.body;
    await withTransaction(async (db) => {
        await assertNotLinked(db, req.params.id);
        await postVoucher(
            db,
            { companyId: req.company!.id, voucherTypeId, voucherNumber, date, narration, entries },
            req.params.id
        );
    });
    res.status(200).json({ status: 'success', message: 'Voucher updated successfully' });
};

export const deleteVoucher = async (req: Request, res: Response) => {
    await withTransaction(async (db) => {
        await assertNotLinked(db, req.params.id);
        await removeVoucher(db, req.company!.id, req.params.id);
    });
    res.status(204).send();
};

export const getVouchers = async (req: Request, res: Response) => {
    const params: any[] = [req.company!.id];
    let sql = `SELECT v.*, vt.name AS voucher_type_name,
                      (SELECT i.id FROM invoices i WHERE i.voucher_id = v.id LIMIT 1) AS invoice_id
               FROM vouchers v LEFT JOIN voucher_types vt ON v.voucher_type_id = vt.id
               WHERE v.company_id = $1`;
    if (req.query.fromDate) {
        params.push(req.query.fromDate);
        sql += ` AND v.date >= $${params.length}`;
    }
    if (req.query.toDate) {
        params.push(req.query.toDate);
        sql += ` AND v.date <= $${params.length}`;
    }
    if (req.query.voucherTypeId) {
        params.push(req.query.voucherTypeId);
        sql += ` AND v.voucher_type_id = $${params.length}`;
    }
    sql += ' ORDER BY v.date DESC, v.created_at DESC';
    const result = await query(sql, params);
    res.status(200).json({ status: 'success', data: { vouchers: result.rows } });
};

export const getVoucherTypes = async (req: Request, res: Response) => {
    const result = await query('SELECT * FROM voucher_types WHERE company_id = $1 ORDER BY name', [req.company!.id]);
    res.status(200).json({ status: 'success', data: { voucherTypes: result.rows } });
};

export const getNextVoucherNumber = async (req: Request, res: Response) => {
    const vt = await query('SELECT name FROM voucher_types WHERE id = $1 AND company_id = $2', [
        req.query.voucherTypeId,
        req.company!.id,
    ]);
    if (!vt.rows.length) throw new AppError('Invalid voucher type', 400);
    const date = toDateString(String(req.query.date || toDateString(new Date())));
    const number = await withTransaction(async (db) => {
        const fy = await resolveFinancialYear(db, req.company!.id, date);
        return peekNextNumber(db, req.company!.id, docTypeForVoucherType(vt.rows[0].name), fy);
    });
    res.status(200).json({ status: 'success', data: { number } });
};

export const getVoucherById = async (req: Request, res: Response) => {
    const v = await query(
        `SELECT v.*, vt.name AS voucher_type_name FROM vouchers v
         LEFT JOIN voucher_types vt ON v.voucher_type_id = vt.id WHERE v.id = $1`,
        [req.params.id]
    );
    const entries = await query(
        `SELECT ve.*, l.name AS ledger_name FROM voucher_entries ve
         LEFT JOIN ledgers l ON ve.ledger_id = l.id WHERE ve.voucher_id = $1
         ORDER BY CASE ve.type WHEN 'Dr' THEN 0 ELSE 1 END, ve.created_at`,
        [req.params.id]
    );
    res.status(200).json({ status: 'success', data: { voucher: v.rows[0], entries: entries.rows } });
};
